CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,is_global INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,totp_secret TEXT,totp_enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,icon_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,icon_id TEXT,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS group_users(group_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES groups(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_tenants(user_id TEXT NOT NULL,tenant_id TEXT NOT NULL,PRIMARY KEY(user_id,tenant_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS permissions(subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,scope_type TEXT NOT NULL,scope_id TEXT NOT NULL DEFAULT '',permission TEXT NOT NULL,PRIMARY KEY(subject_type,subject_id,scope_type,scope_id,permission));
CREATE TABLE IF NOT EXISTS app_instances(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,app_id TEXT NOT NULL,name TEXT NOT NULL,version TEXT NOT NULL,style_id TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS repositories(id TEXT PRIMARY KEY,url TEXT UNIQUE NOT NULL,trusted INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,user_id TEXT,event TEXT NOT NULL,data TEXT NOT NULL);
